```js
async function promiseAllLimit(fns, limit) {
  const results = new Array(fns.length);
  let i = 0;
  async function worker() {
    while (i < fns.length) {
      const idx = i++;
      results[idx] = await fns[idx]();
    }
  }
  await Promise.all(Array.from({ length: Math.min(limit, fns.length) }, worker));
  return results;
}
```
Accepts array of thunks (functions returning promises) so we control when each starts.

```js
function once(fn) {
  let called = false, result;
  return function(...args) {
    if (!called) { called = true; result = fn.apply(this, args); }
    return result;
  };
}
```
Handy for bootstrap code, singleton constructors.
